      { text: "Ist das euere Katze?", correct: false, explain: "Classic trap! Germans never say 'euere'; the middle 'e' drops to form 'eure'!" },
      { text: "Ist das ihr Katze?", correct: false, explain: "For 'ihr' (you all) with feminine, use 'eure'!" }
